// "Discover myself": guided reflection exercises -> AI-written personal growth map.
// Answers autosave to Supabase (own row, RLS). The map is generated by the `discover-map` Edge Function.
(() => {
  const { t, esc, hooks, $ } = App;
  if (!$('p-questions')) return;
  const D = DISC;
  const L = (item, enI, azI) => (App.lang === 'az' ? item[azI] : item[enI]);
  const name = (list, id, enI = 1, azI = 2) => { const it = list.find(x => x[0] === id); return it ? L(it, enI, azI) : id; };
  const NEXT = { questions: 'strengths', strengths: 'values', values: 'interests', interests: 'comm', comm: 'goals', goals: 'map' };

  let A = { q: {}, strengths: { picked: [], examples: {} }, values: { picked: [], ranked: [], rating: {} }, interests: { picked: [], dream: '' },
    comm: {}, traits: { picked: [], why: '' }, goals: [{}, {}, {}], mapDone: {} };
  let MAP = null, MAP_AT = null, generating = false, mapErr = '';

  // ---------- autosave ----------
  let saveT;
  const setState = k => { $('saveState').textContent = t(k); $('saveState').dataset.k = k; };
  async function flush() {
    A.values.ranked = A.values.picked.slice(0, 5);
    if (!Auth.user) return true;
    const { error } = await Auth.sb.from('discoveries').upsert({ user_id: Auth.user.id, answers: A, updated_at: new Date().toISOString() }, { onConflict: 'user_id' });
    if (error) { console.error('discoveries save failed', error); clearTimeout(saveT); saveT = setTimeout(flush, 4000); }   // keep answers in memory and retry
    setState(error ? 'Could not save. Please try again.' : 'All changes saved');
    return !error;
  }
  const touch = () => { setState('Saving…'); clearTimeout(saveT); saveT = setTimeout(flush, 800); marks(); };

  // ---------- progress ----------
  const answeredQ = () => Object.values(A.q).filter(v => (v || '').trim().length >= 5).length;
  const goalsFilled = () => A.goals.filter(g => (g.text || '').trim()).length;
  const STATUS = {
    questions: () => answeredQ() >= 4, strengths: () => A.strengths.picked.length >= 3, values: () => A.values.picked.length >= 3,
    interests: () => A.interests.picked.length >= 1, comm: () => D.comm.every(c => A.comm[c[0]]), goals: () => goalsFilled() >= 1, map: () => !!MAP,
  };
  const ready = () => answeredQ() >= 3 && A.strengths.picked.length >= 3 && A.values.picked.length >= 3 && goalsFilled() >= 1;
  function marks() {
    document.querySelectorAll('#dTabs [data-tab]').forEach(b => b.classList.toggle('done', !!STATUS[b.dataset.tab]()));
    const rb = $('genMap'); if (rb) rb.disabled = !ready() || generating;
  }
  const nextBtn = tab => NEXT[tab] ? `<button class="btn btn-dark btn-block" type="button" data-go="${NEXT[tab]}">${esc(t('Continue'))}</button>` : '';
  const bindNav = root => root.querySelectorAll('[data-go]').forEach(b => b.onclick = () => { location.hash = b.dataset.go; window.scrollTo({ top: 0, behavior: 'smooth' }); });

  // ---------- 1. questions ----------
  function paintQuestions() {
    $('p-questions').innerHTML = `<div class="panel"><h3>${esc(t('Know yourself'))}</h3>
      <p class="muted">${esc(t('Answer at least 4 questions in your own words. There are no right answers. Short is fine.'))}</p>
      ${D.questions.map(q => `<label class="lbl" for="${q[0]}">${esc(L(q, 1, 2))}</label>
        <textarea id="${q[0]}" rows="3" maxlength="900">${esc(A.q[q[0]] || '')}</textarea>`).join('')}
      ${nextBtn('questions')}</div>`;
    D.questions.forEach(q => { $(q[0]).oninput = e => { A.q[q[0]] = e.target.value; touch(); }; });
    bindNav($('p-questions'));
  }

  // ---------- 2. strengths ----------
  function paintStrengths() {
    const P = A.strengths.picked;
    $('p-strengths').innerHTML = `<div class="panel"><h3>${esc(t('Your strengths'))}</h3>
      <p class="muted">${esc(t('Pick up to 5 strengths that sound most like the real you, not the person you wish you were.'))} <b>${P.length}/5</b></p>
      <div class="pick-grid">${D.strengths.map(s => `<button type="button" class="pick ${P.includes(s[0]) ? 'on' : ''}" data-id="${s[0]}">
        <strong>${esc(L(s, 1, 2))}</strong><small>${esc(L(s, 3, 4))}</small></button>`).join('')}</div>
      ${P.length ? `<h4 class="sub-h">${esc(t('A real example for each'))}</h4><p class="muted small">${esc(t('When did you recently use this strength? One or two sentences.'))}</p>
        ${P.map(id => `<label class="lbl" for="ex-${id}">${esc(name(D.strengths, id))}</label>
          <textarea id="ex-${id}" rows="2" maxlength="500">${esc(A.strengths.examples[id] || '')}</textarea>`).join('')}` : ''}
      <p class="muted small">${esc(t('Tip: ask two people who know you well which strengths they see in you.'))}</p>
      ${nextBtn('strengths')}</div>`;
    $('p-strengths').querySelectorAll('.pick').forEach(b => b.onclick = () => {
      const i = P.indexOf(b.dataset.id);
      if (i >= 0) P.splice(i, 1); else if (P.length < 5) P.push(b.dataset.id);
      touch(); paintStrengths();
    });
    P.forEach(id => { $('ex-' + id).oninput = e => { A.strengths.examples[id] = e.target.value; touch(); }; });
    bindNav($('p-strengths'));
  }

  // ---------- 3. values ----------
  function paintValues() {
    const P = A.values.picked;
    $('p-values').innerHTML = `<div class="panel"><h3>${esc(t('Your values'))}</h3>
      <p class="muted">${esc(t('Values are what matters to you, the kind of person you want to be. Choose up to 8, then put them in order.'))} <b>${P.length}/8</b></p>
      <div class="chips pick-chips">${D.values.map(v => `<button type="button" class="chip-btn ${P.includes(v[0]) ? 'on' : ''}" data-id="${v[0]}">${esc(L(v, 1, 2))}</button>`).join('')}</div>
      ${P.length ? `<h4 class="sub-h">${esc(t('Put them in order, most important first'))}</h4>
        <ol class="rank">${P.map((id, i) => `<li class="${i < 5 ? 'top' : ''}"><span class="rk">${i + 1}</span><span class="rn">${esc(name(D.values, id))}</span>
          <button type="button" class="x" data-up="${i}" ${i === 0 ? 'disabled' : ''} aria-label="${esc(t('Move up'))}">↑</button>
          <button type="button" class="x" data-dn="${i}" ${i === P.length - 1 ? 'disabled' : ''} aria-label="${esc(t('Move down'))}">↓</button></li>`).join('')}</ol>
        <h4 class="sub-h">${esc(t('How much does your life today reflect each of your top 5?'))}</h4>
        <p class="muted small">0 = ${esc(t('not at all'))}, 10 = ${esc(t('completely'))}</p>
        ${P.slice(0, 5).map(id => `<div class="slider"><label for="r-${id}">${esc(name(D.values, id))}</label>
          <input type="range" id="r-${id}" min="0" max="10" step="1" value="${A.values.rating[id] ?? 5}"><b id="rv-${id}">${A.values.rating[id] ?? '–'}</b></div>`).join('')}` : ''}
      ${nextBtn('values')}</div>`;
    $('p-values').querySelectorAll('.chip-btn').forEach(b => b.onclick = () => {
      const i = P.indexOf(b.dataset.id);
      if (i >= 0) P.splice(i, 1); else if (P.length < 8) P.push(b.dataset.id);
      touch(); paintValues();
    });
    const mv = (i, d) => { [P[i], P[i + d]] = [P[i + d], P[i]]; touch(); paintValues(); };
    $('p-values').querySelectorAll('[data-up]').forEach(b => b.onclick = () => mv(+b.dataset.up, -1));
    $('p-values').querySelectorAll('[data-dn]').forEach(b => b.onclick = () => mv(+b.dataset.dn, 1));
    P.slice(0, 5).forEach(id => { $('r-' + id).oninput = e => { A.values.rating[id] = +e.target.value; $('rv-' + id).textContent = e.target.value; touch(); }; });
    bindNav($('p-values'));
  }

  // ---------- 4. interests ----------
  function paintInterests() {
    const P = A.interests.picked;
    $('p-interests').innerHTML = `<div class="panel"><h3>${esc(t('Your interests'))}</h3>
      <p class="muted">${esc(t('What are you drawn to? Pick up to 6. Choose by curiosity, not by what is useful.'))} <b>${P.length}/6</b></p>
      <div class="chips pick-chips">${D.interests.map(v => `<button type="button" class="chip-btn ${P.includes(v[0]) ? 'on' : ''}" data-id="${v[0]}">${esc(L(v, 1, 2))}</button>`).join('')}</div>
      <label class="lbl" for="dream">${esc(t('If fear and time were not a problem, what would you try or learn?'))}</label>
      <textarea id="dream" rows="3" maxlength="900">${esc(A.interests.dream || '')}</textarea>
      ${nextBtn('interests')}</div>`;
    $('p-interests').querySelectorAll('.chip-btn').forEach(b => b.onclick = () => {
      const i = P.indexOf(b.dataset.id);
      if (i >= 0) P.splice(i, 1); else if (P.length < 6) P.push(b.dataset.id);
      touch(); paintInterests();
    });
    $('dream').oninput = e => { A.interests.dream = e.target.value; touch(); };
    bindNav($('p-interests'));
  }

  // ---------- 5. communication & boundaries ----------
  const snapshot = () => {
    const rated = D.comm.filter(c => A.comm[c[0]]);
    if (rated.length < D.comm.length) return '';
    const avg = (rated.reduce((s, c) => s + A.comm[c[0]], 0) / rated.length).toFixed(1);
    const low = rated.slice().sort((a, b) => A.comm[a[0]] - A.comm[b[0]]).slice(0, 3).filter(c => A.comm[c[0]] <= 3);
    return `<div class="snap"><h4>${esc(t('Your snapshot'))}</h4>
      ${rated.map(c => `<div class="bar-row"><span>${esc(L(c, 1, 2))}</span><i class="bar"><u style="width:${A.comm[c[0]] * 20}%"></u></i><em>${A.comm[c[0]]}/5</em></div>`).join('')}
      <p class="muted small">${esc(t('Average'))}: ${avg}/5. ${low.length ? esc(t('Good places to practise first')) + ': ' + low.map(c => '“' + esc(L(c, 1, 2)) + '”').join('; ') : esc(t('You already do many of these. Notice which one you want to strengthen.'))}</p></div>`;
  };
  function paintComm() {
    $('p-comm').innerHTML = `<div class="panel"><h3>${esc(t('Communication and boundaries'))}</h3>
      <p class="muted">${esc(t('How true is each sentence for you in daily life? 1 = not true, 5 = very true. This is a self-reflection, not a test.'))}</p>
      ${D.comm.map(c => `<div class="likert"><p>${esc(L(c, 1, 2))}</p><div class="scale" data-id="${c[0]}">
        ${[1, 2, 3, 4, 5].map(n => `<button type="button" class="${A.comm[c[0]] === n ? 'on' : ''}" data-n="${n}">${n}</button>`).join('')}</div></div>`).join('')}
      ${snapshot()}
      <label class="lbl" for="scenario">${esc(t('Describe one situation where setting a boundary or speaking up is hard for you (who, what happens, what you usually do).'))}</label>
      <textarea id="scenario" rows="4" maxlength="900">${esc(A.comm.scenario || '')}</textarea>
      ${nextBtn('comm')}</div>`;
    $('p-comm').querySelectorAll('.scale').forEach(sc => sc.querySelectorAll('button').forEach(b => b.onclick = () => {
      A.comm[sc.dataset.id] = +b.dataset.n; touch(); const y = window.scrollY; paintComm(); window.scrollTo(0, y);
    }));
    $('scenario').oninput = e => { A.comm.scenario = e.target.value; touch(); };
    bindNav($('p-comm'));
  }

  // ---------- 6. growth traits + weekly goals ----------
  function paintGoals() {
    const T = A.traits.picked, vals = A.values.picked.slice(0, 5);
    $('p-goals').innerHTML = `<div class="panel"><h3>${esc(t('What do you want to grow?'))}</h3>
      <p class="muted">${esc(t('Pick up to 3 qualities you want to develop.'))} <b>${T.length}/3</b></p>
      <div class="chips pick-chips">${D.traits.map(v => `<button type="button" class="chip-btn ${T.includes(v[0]) ? 'on' : ''}" data-id="${v[0]}">${esc(L(v, 1, 2))}</button>`).join('')}</div>
      <label class="lbl" for="twhy">${esc(t('Why these? What would change in your life?'))}</label>
      <textarea id="twhy" rows="3" maxlength="900">${esc(A.traits.why || '')}</textarea></div>
      <div class="panel"><h3>${esc(t('Your goals for this week'))}</h3>
      <p class="muted">${esc(t('Make them small: something you can do in 30 minutes or less this week. Add an if-then plan, because it makes follow-through much more likely.'))}</p>
      ${A.goals.map((g, i) => `<div class="goal-row"><b class="opt-n">${i + 1}</b><div>
        <input class="inp" data-f="text" data-i="${i}" maxlength="200" value="${esc(g.text || '')}" placeholder="${esc(t('My goal, e.g. Say no to one request I do not want to take on'))}">
        <select class="inp" data-f="value" data-i="${i}"><option value="">${esc(t('Linked value (optional)'))}</option>
          ${vals.map(v => `<option value="${v}" ${g.value === v ? 'selected' : ''}>${esc(name(D.values, v))}</option>`).join('')}</select>
        <input class="inp" data-f="ifthen" data-i="${i}" maxlength="250" value="${esc(g.ifthen || '')}" placeholder="${esc(t('If it is Tuesday after work, then I will…'))}"></div></div>`).join('')}
      ${nextBtn('goals')}</div>`;
    $('p-goals').querySelectorAll('.chip-btn').forEach(b => b.onclick = () => {
      const i = T.indexOf(b.dataset.id);
      if (i >= 0) T.splice(i, 1); else if (T.length < 3) T.push(b.dataset.id);
      touch(); paintGoals();
    });
    $('twhy').oninput = e => { A.traits.why = e.target.value; touch(); };
    $('p-goals').querySelectorAll('[data-f]').forEach(el => el.oninput = el.onchange = e => { A.goals[+el.dataset.i][el.dataset.f] = e.target.value; touch(); });
    bindNav($('p-goals'));
  }

  // ---------- 7. map ----------
  const li = arr => (arr || []).length ? `<ul>${arr.map(x => `<li>${esc(x)}</li>`).join('')}</ul>` : '';
  function mapHtml(m) {
    const top = A.values.picked.slice(0, 5);
    return `<div class="gm">
      <div class="panel gm-intro"><p class="eyebrow">${esc(t('Your growth map'))}</p><p>${esc(m.intro)}</p>
        ${MAP_AT ? `<small class="muted">${esc(t('Created'))}: ${esc(new Date(MAP_AT).toLocaleString(App.lang === 'az' ? 'az-Latn-AZ' : App.lang))}</small>` : ''}</div>
      ${m.support_note ? `<div class="alert-box"><i>${icon('alert')}</i><p>${esc(m.support_note)}</p></div>` : ''}
      <h3 class="gm-h">⭐ ${esc(t('Your strengths'))}</h3>
      <div class="gm-grid">${m.strengths.map(s => `<article class="gm-card"><h4>${esc(s.name)}</h4><p class="q">“${esc(s.evidence)}”</p><p><b>${esc(t('This week'))}:</b> ${esc(s.how_to_use)}</p></article>`).join('')}</div>
      <h3 class="gm-h">🧭 ${esc(t('Your values'))}</h3>
      <div class="gm-grid">${m.values.map((v, i) => {
        const id = top.find(x => name(D.values, x).toLowerCase() === (v.name || '').toLowerCase()) || top[i];
        const r = id != null ? A.values.rating[id] : null;
        return `<article class="gm-card"><h4>${i + 1}. ${esc(v.name)}</h4><p>${esc(v.why_it_matters)}</p>
          ${r != null ? `<div class="bar-row"><span>${esc(t('Living it now'))}</span><i class="bar"><u style="width:${r * 10}%"></u></i><em>${r}/10</em></div>` : ''}
          <p class="muted">${esc(v.insight)}</p></article>`; }).join('')}</div>
      ${(m.value_gaps || []).length ? `<div class="gm-card wide"><h4>${esc(t('Where life and values are not yet aligned'))}</h4>${m.value_gaps.map(g => `<p><b>${esc(g.value)}:</b> ${esc(g.gap_note)}<br><span class="muted">→ ${esc(g.small_action)}</span></p>`).join('')}</div>` : ''}
      <h3 class="gm-h">🌱 ${esc(t('Interests to explore'))}</h3>
      <div class="gm-card wide">${(m.interests.themes || []).length ? `<p><b>${esc(t('Themes I notice'))}:</b></p>${li(m.interests.themes)}` : ''}
        <p><b>${esc(t('Small experiments to try'))}:</b></p>${li(m.interests.directions)}</div>
      <h3 class="gm-h">💬 ${esc(t('Communication and boundaries'))}</h3>
      <div class="gm-card wide">${(m.communication.strengths || []).length ? `<p><b>${esc(t('Already working for you'))}:</b></p>${li(m.communication.strengths)}` : ''}
        ${(m.communication.growth_areas || []).map(g => `<p><b>${esc(g.area)}</b><br>${esc(g.why)}<br><span class="muted">${esc(t('Practice'))}: ${esc(g.practice)}</span></p>`).join('')}
        ${m.communication.boundary_script && m.communication.boundary_script.script ? `<div class="script"><b>${esc(t('A script for your situation'))}</b>
          <p class="muted small">${esc(m.communication.boundary_script.situation)}</p><blockquote>${esc(m.communication.boundary_script.script)}</blockquote></div>` : ''}</div>
      <h3 class="gm-h">🚀 ${esc(t('Where you could grow'))}</h3>
      <div class="gm-grid">${m.growth_directions.map(g => `<article class="gm-card"><h4>${esc(g.title)}</h4><p>${esc(g.why)}</p><ol>${g.first_steps.map(s => `<li>${esc(s)}</li>`).join('')}</ol></article>`).join('')}</div>
      <h3 class="gm-h">🎯 ${esc(t('Your goals for this week'))}</h3>
      <div class="gm-card wide">${m.weekly_goals.map((g, i) => `<label class="gm-goal"><input type="checkbox" data-mg="${i}" ${A.mapDone[i] ? 'checked' : ''}>
        <span><b>${esc(g.goal)}</b><small>${esc(g.if_then)}</small><small class="muted">${esc(t('How I will know'))}: ${esc(g.measure)}${g.linked_value ? ' · ' + esc(g.linked_value) : ''}</small></span></label>`).join('')}</div>
      <h3 class="gm-h">💭 ${esc(t('Questions to keep thinking about'))}</h3>
      <div class="gm-card wide">${li(m.reflection_questions)}</div>
      <p class="muted small center">${esc(m.note)}</p>
    </div>`;
  }
  function paintMap() {
    const checks = [[answeredQ() >= 3, 'At least 3 answers in “Know yourself”', 'questions'], [A.strengths.picked.length >= 3, 'At least 3 strengths', 'strengths'],
      [A.values.picked.length >= 3, 'At least 3 values', 'values'], [goalsFilled() >= 1, 'At least 1 weekly goal', 'goals']];
    $('p-map').innerHTML = `${MAP ? mapHtml(MAP) : ''}
      <div class="panel">${MAP ? `<h3>${esc(t('Update your map'))}</h3><p class="muted small">${esc(t('Changed your answers? Create the map again. It replaces the old one.'))}</p>`
        : `<h3>${esc(t('Create your growth map'))}</h3>
        <ul class="ready">${checks.map(c => `<li class="${c[0] ? 'ok' : ''}">${c[0] ? '✓' : '○'} ${c[0] ? esc(t(c[1])) : `<a href="#${c[2]}">${esc(t(c[1]))}</a>`}</li>`).join('')}</ul>`}
        <button class="btn btn-dark btn-block" id="genMap" type="button" ${ready() && !generating ? '' : 'disabled'}>${esc(t(generating ? 'Aisha is writing your map (about a minute)…' : MAP ? 'Create the map again' : 'Create my growth map'))}</button>
        ${mapErr ? `<p class="form-msg err">${esc(t(mapErr))}</p>` : ''}
        <p class="muted small center">${esc(t('A reflection tool, not a diagnosis or a fixed verdict about you.'))}</p></div>`;
    $('genMap').onclick = generate;
    $('p-map').querySelectorAll('[data-mg]').forEach(c => c.onchange = () => { A.mapDone[c.dataset.mg] = c.checked; touch(); });
  }
  async function generate() {
    if (generating || !ready()) return;
    generating = true; mapErr = ''; paintMap();
    try {
      clearTimeout(saveT);
      if (!await flush()) throw new Error('save');
      const { data, error } = await Auth.sb.functions.invoke('discover-map', { body: { lang: App.lang } });
      if (error) {
        let code = 'failed';
        try { code = (await error.context.json()).error || code; } catch (e) {}
        throw new Error(code);
      }
      MAP = data.map; MAP_AT = data.map_at; A.mapDone = {};
    } catch (e) {
      console.error('discover-map failed', e);
      mapErr = e.message === 'rate_limited' ? 'You created the map several times today. Please try again tomorrow.'
        : e.message === 'not_enough_answers' ? 'Please answer a bit more first.' : 'Could not create the map. Please try again.';
    } finally {
      generating = false; paintMap(); marks();
      if (MAP) window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  }

  // ---------- boot ----------
  const paintAll = () => { paintQuestions(); paintStrengths(); paintValues(); paintInterests(); paintComm(); paintGoals(); paintMap(); marks(); };
  hooks.push(() => { if ($('saveState').dataset.k) $('saveState').textContent = t($('saveState').dataset.k); if (loaded) paintAll(); });
  let loaded = false;

  (async () => {
    if (!Auth.configured) return;
    const user = await Auth.require();
    if (!user) return;
    const { data } = await Auth.sb.from('discoveries').select('answers, map, map_at').eq('user_id', user.id).maybeSingle();
    if (data) {
      const a = data.answers || {};
      A = { ...A, ...a, q: a.q || {}, strengths: { picked: [], examples: {}, ...(a.strengths || {}) }, values: { picked: [], ranked: [], rating: {}, ...(a.values || {}) },
        interests: { picked: [], dream: '', ...(a.interests || {}) }, comm: a.comm || {}, traits: { picked: [], why: '', ...(a.traits || {}) },
        goals: [0, 1, 2].map(i => (a.goals || [])[i] || {}), mapDone: a.mapDone || {} };
      MAP = data.map; MAP_AT = data.map_at;
    }
    loaded = true; paintAll();
  })();
})();
